@Override
    public void render(TileEnderChest enderChest, float partialTicks, PoseStack mStack, MultiBufferSource getter, int packedLight, int packedOverlay) {
        CCRenderState ccrs = CCRenderState.instance();
        ccrs.brightness = packedLight;
        ccrs.overlay = packedOverlay;
        renderChest(ccrs, mStack, getter, enderChest.rotation, enderChest.getFrequency(), (float) enderChest.getRadianLidAngle(partialTicks), RenderUtils.getTimeOffset(enderChest.getBlockPos()));
    }

public void renderChest(CCRenderState ccrs, PoseStack pose, MultiBufferSource source, int rotation, Frequency freq, float lidAngle, int pearlOffset) {
        Matrix4 mat = new Matrix4(pose);
        if (lidAngle != 0) {
            renderEndPortal.render(mat, source);
        }
        ccrs.reset();

        // Render chest
        pose.pushPose();
        pose.translate(0, 1.0, 1.0);
        pose.scale(1.0F, -1.0F, -1.0F);
        pose.translate(0.5, 0.5, 0.5);
        pose.mulPose(new Quaternionf().rotateXYZ(0, (float) (rotation * 90F * MathHelper.torad), 0));
        pose.translate(-0.5, -0.5, -0.5);
        VertexConsumer chestCons = source.getBuffer(chestType);
        lid.xRot = lidAngle;
        lock.xRot = lidAngle;
        diamondLock.xRot = lidAngle;
        lid.render(pose, chestCons, ccrs.brightness, ccrs.overlay);
        bottom.render(pose, chestCons, ccrs.brightness, ccrs.overlay);
        if (freq.hasOwner()) {
            diamondLock.render(pose, chestCons, ccrs.brightness, ccrs.overlay);
        } else {
            lock.render(pose, chestCons, ccrs.brightness, ccrs.overlay);
        }
        pose.popPose();

        mat.translate(0.5, 0, 0.5);
        // Buttons
        ccrs.bind(buttonType, source);
        Matrix4 buttonCommon = mat.copy();
        buttonCommon.rotate((-90 * (rotation)) * MathHelper.torad, Vector3.Y_POS);
        buttonCommon.apply(new Rotation(lidAngle, 1, 0, 0).at(new Vector3(-8 / 16D, 9D / 16D, -7 / 16D)));

        EnumColour[] colours = freq.toArray();
        for (int i = 0; i < 3; i++) {
            Matrix4 buttonMat = buttonCommon.copy();
            buttonMat.apply(BlockEnderChest.buttonT[i]);
            ButtonModelLibrary.button.render(ccrs, buttonMat, new UVTranslation(0.25 * (colours[i].getWoolMeta() % 4), 0.25 * (colours[i].getWoolMeta() / 4)));
        }

        // Pearl
        if (lidAngle != 0) {
            double time = ClientUtils.getRenderTime() + pearlOffset;
            Matrix4 pearlMat = RenderUtils.getMatrix(mat.copy(), new Vector3(0, 0.2 + lidAngle * -0.5 + RenderUtils.getPearlBob(time), 0), new Rotation(time / 3, new Vector3(0, 1, 0)), 0.04);
            ccrs.brightness = 15728880;
            ccrs.bind(pearlType, source);
            CCModelLibrary.icosahedron4.render(ccrs, pearlMat);
        }
        ccrs.reset();
    }

@Override
    public void render(TileEnderTank enderTank, float partialTicks, PoseStack mStack, MultiBufferSource source, int packedLight, int packedOverlay) {
        CCRenderState ccrs = CCRenderState.instance();
        ccrs.brightness = packedLight;
        ccrs.overlay = packedOverlay;
        float valveRot = (float) MathHelper.interpolate(enderTank.pressure_state.b_rotate, enderTank.pressure_state.a_rotate, partialTicks) * 0.01745F;
        int pearlOffset = RenderUtils.getTimeOffset(enderTank.getBlockPos());
        Matrix4 mat = new Matrix4(mStack);
        renderTank(ccrs, mat.copy(), source, enderTank.rotation, valveRot, enderTank.getFrequency(), pearlOffset);
        renderFluid(ccrs, mat, source, enderTank.liquid_state.c_liquid);
        ccrs.reset();
    }

public static void renderTank(CCRenderState ccrs, Matrix4 mat, MultiBufferSource buffers, int rotation, float valveRot, Frequency freq, int pearlOffset) {
        renderEndPortal.render(mat, buffers);
        ccrs.reset();
        mat.translate(0.5, 0, 0.5);
        mat.rotate((-90 * (rotation + 2)) * MathHelper.torad, Vector3.Y_POS);
        ccrs.bind(baseType, buffers);
        tankModel.render(ccrs, mat);
        Matrix4 valveMat = mat.copy().apply(new Rotation(valveRot, Vector3.Z_POS).at(new Vector3(0, 0.4165, 0)));
        valveModel.render(ccrs, valveMat, new UVTranslation(0, freq.hasOwner() ? 13 / 64D : 0));

        ccrs.bind(buttonType, buffers);
        EnumColour[] colours = freq.toArray();
        for (int i = 0; i < 3; i++) {
            //noinspection IntegerDivisionInFloatingPointContext
            buttons[i].render(ccrs, mat, new UVTranslation(0.25 * (colours[i].getWoolMeta() % 4), 0.25 * (colours[i].getWoolMeta() / 4)));
        }

        double time = ClientUtils.getRenderTime() + pearlOffset;
        Matrix4 pearlMat = RenderUtils.getMatrix(mat.copy(), new Vector3(0, 0.45 + RenderUtils.getPearlBob(time) * 2, 0), new Rotation(time / 3, Vector3.Y_POS), 0.04);
        ccrs.brightness = 15728880;
        ccrs.bind(pearlType, buffers);
        CCModelLibrary.icosahedron4.render(ccrs, pearlMat);
        ccrs.reset();
    }

public static void renderFluid(CCRenderState ccrs, Matrix4 mat, MultiBufferSource getter, FluidStack stack) {
        RenderUtils.renderFluidCuboid(ccrs, mat, RenderUtils.getFluidRenderType(), getter, stack, new Cuboid6(0.22, 0.12, 0.22, 0.78, 0.121 + 0.63, 0.78), stack.getAmount() / (16D * FluidUtils.B), 0.75);
    }

public static void load() {
        LOCK.lock();

        config = new ConfigFile(MOD_ID)
                .path(Paths.get("./config/EnderStorage.cfg"))
                .load();
//        ConfigSyncManager.registerSync(new ResourceLocation("enderstorage:config"), config);
        personalItemTag = config.getValue("personalItem")
                .setComment("The RegistryName for the Item to lock EnderChests and Tanks.")
                .setDefaultString("minecraft:diamond");
        anarchyMode = config.getValue("anarchyMode")
                .setComment("Causes chests to lose personal settings and drop the diamond on break.")
                .setDefaultBoolean(false)
                .getBoolean();
        storageSize = config.getValue("item_storage_size")
                .setComment("The size of each inventory of EnderStorage, 0 = 3x3, 1 = 3x9, 2 = 6x9, default = 1")
                .setDefaultInt(1)
                .getInt();

        disableCreatorVisuals = config.getValue("disableCreatorVisuals")
                .setComment("Disables the tank on top of creators heads.")
                .setDefaultBoolean(false)
                .getBoolean();
        useVanillaEnderChestSounds = config.getValue("useVanillaEnderChestsSounds")
                .setComment("Enable this to make EnderStorage use vanilla's EnderChest sounds instead of the standard chest.")
                .setDefaultBoolean(false)
                .getBoolean();
        config.save();
