public EnderKnobSlot(int meta) {
        Vector3[] verts = new Vector3[8];
        verts[0] = new Vector3(-0.0625, 0.4375, -0.5);
        verts[1] = new Vector3(0.0625, 0.4375, -0.5);
        verts[3] = new Vector3(-0.0625, 0.4375, -0.4375);
        verts[2] = new Vector3(0.0625, 0.4375, -0.4375);
        verts[5] = new Vector3(-0.0625, 0.6875, -0.5);
        verts[4] = new Vector3(0.0625, 0.6875, -0.5);
        verts[6] = new Vector3(-0.0625, 0.6875, -0.4375);
        verts[7] = new Vector3(0.0625, 0.6875, -0.4375);

        for (int i = 0; i < 8; i++) {
            verts[i].rotate((meta + 2) * -0.5 * 3.14159, new Vector3(0, 1, 0));
            verts[i].add(0.5, 0, 0.5);
        }

        aabb = cornersToAABB(verts);
    }

public AABB getSelectionBB() {
        return aabb;
    }

public static AABB cornersToAABB(Vector3[] corners) {
        Vector3 min = corners[0].copy();
        Vector3 max = corners[0].copy();
        for (int i = 1; i < corners.length; i++) {
            Vector3 vec = corners[i];
            if (vec.x < min.x) {
                min.x = vec.x;
            } else if (vec.x > max.x) {
                max.x = vec.x;
            }
            if (vec.y < min.y) {
                min.y = vec.y;
            } else if (vec.y > max.y) {
                max.y = vec.y;
            }
            if (vec.z < min.z) {
                min.z = vec.z;
            } else if (vec.z > max.z) {
                max.z = vec.z;
            }
        }
        return new AABB(min.x, min.y, min.z, max.x, max.y, max.z);
    }

@Override
    public void handlePacket(PacketCustom packet, Minecraft mc, ClientPacketListener handler) {
        switch (packet.getType()) {
            case C_TILE_UPDATE:
                if (mc.level.getBlockEntity(packet.readPos()) instanceof TileFrequencyOwner tile) {
                    tile.readFromPacket(packet);
                }
                break;
            case C_SET_CLIENT_OPEN:
                EnderStorageManager.instance(true).getStorage(Frequency.readFromPacket(packet), EnderItemStorage.TYPE).setClientOpen(packet.readBoolean() ? 1 : 0);
                break;
            case C_TANK_SYNC:
                TankSynchroniser.syncClient(Frequency.readFromPacket(packet), packet.readFluidStack());
                break;
            case C_LIQUID_SYNC:
                if (mc.level.getBlockEntity(packet.readPos()) instanceof TileEnderTank tile) {
                    tile.liquid_state.sync(packet.readFluidStack());
                }
                break;
            case C_PRESSURE_SYNC:
                if (mc.level.getBlockEntity(packet.readPos()) instanceof TileEnderTank tile) {
                    tile.pressure_state.a_pressure = packet.readBoolean();
                }
                break;
        }
    }

