    public ItemStack assemble(CraftingContainer inv, RegistryAccess pRegistryAccess) {
        EnumColour colour = EnumColour.WHITE;
        finish:
        for (int x = 0; x < 3; x++) {
            for (int y = 0; y < 3; y++) {
                ItemStack stack = inv.getItem(x + y * inv.getWidth());
                if (!stack.isEmpty()) {
                    EnumColour c = EnumColour.fromWoolStack(stack);
                    if (c != null) {
                        colour = c;
