    @Override
    public BlockState getStateForPlacement(BlockPlaceContext ctx) {
        BlockState state = defaultBlockState();
        for (StateAwareComponent component : stateComponents) {
            state = component.getStateForPlacement(state, ctx);
            if (state == null) break;
        }
        return state;
    }

