        this.serializer = serializer;
        return this;
    }

public ConfigCategory load() {
        if (path == null) throw new IllegalStateException("Path has not been set.");
        if (serializer == null) throw new IllegalStateException("Serializer was not automatically detected from file extension.");

        ConfigCategoryImpl rootTag = new ConfigCategoryImpl(rootName, null) {
            @Override
            public void save() {
                if (isDirty()) {
                    try {
                        serializer.save(path, this);
                    } catch (IOException ex) {
                        LOGGER.error("Failed to save config file! {}", path, ex);
                    }
                    clearDirty();
                }
            }
        };
        if (Files.exists(path)) {
            try {
                serializer.parse(path, rootTag);
            } catch (Throwable ex) {
                rootTag.clear();
                rootTag.clearDirty();
                Path backup = moveToBackup(path);
                LOGGER.warn("Failed to load config {} - Backing up to '{}' and generating a new one.", path, backup, ex);
            }
        }
        return rootTag;
    }

@Override
            public void save() {
                if (isDirty()) {
                    try {
                        serializer.save(path, this);
                    } catch (IOException ex) {
                        LOGGER.error("Failed to save config file! {}", path, ex);
                    }
                    clearDirty();
                }
            }

@Nullable
    @VisibleForTesting
    static ConfigSerializer pickForExtension(Path path) {
        String ext = FilenameUtils.getExtension(path.getFileName().toString());
        return switch (ext) {
            case "cfg" -> ConfigSerializer.LEGACY;
            case "json" -> ConfigSerializer.JSON;
            case "toml" -> ConfigSerializer.TOML;
            default -> null;
        };
    }

@Nullable
    @VisibleForTesting
    static Path moveToBackup(Path path) {
        try {
            String fName = path.getFileName().toString();
            String ext = FilenameUtils.getExtension(fName);
            int curr = ext.startsWith("bak") ? Integer.parseInt(ext.substring(3)) : 0;
            int next = curr + 1;
            Path newFile = path.resolveSibling((ext.startsWith("bak") ? removeExtension(fName) : fName) + ".bak" + next);
            if (next == 6) { // Only keep 5 backups, delete if 5th file would be moved to 6th.
                Files.delete(path);
                return null;
            }
            if (Files.exists(newFile)) {
                moveToBackup(newFile);
            }
            Files.move(path, newFile);
            return newFile;
        } catch (IOException ex) {
            throw new RuntimeException("Failed to move config file.", ex);
        }
    }

public static void registerSync(ResourceLocation key, ConfigTag tag) {
        ConfigTag prev = SYNC_MAP.put(key, tag);
        if (prev != null) {
            throw new IllegalArgumentException("Key '" + key + "' already registered.");
        }
    }

public static void handleLogin(BiConsumer<String, Supplier<PacketCustom>> consumer) {
        if (SYNC_MAP.isEmpty()) return;

        consumer.accept("config_sync", () -> {
            PacketCustom packet = new PacketCustom(NET_CHANNEL, L_CONFIG_SYNC);
            packet.writeVarInt(SYNC_MAP.size());
            for (Map.Entry<ResourceLocation, ConfigTag> entry : SYNC_MAP.entrySet()) {
                packet.writeResourceLocation(entry.getKey());
                entry.getValue().write(packet);
            }

            String mods = Joiner.on(", ").join(SYNC_MAP.keySet());
            LOGGER.info("Sending config sync packet for {} to connecting player.", mods);
            return packet;
        });
    }

public static void readSyncPacket(PacketCustom packet) {
        int numPackets = packet.readVarInt();
        for (int i = 0; i < numPackets; i++) {
            ResourceLocation ident = packet.readResourceLocation();
            LOGGER.info("Applying config sync for {}.", ident);
            ConfigTag config = SYNC_MAP.get(ident);
            if (config == null) {
                LOGGER.fatal("Client is missing sync tag: {}. Potentially skipped other configs!", ident);
                return;
            }
            config.read(packet);
            config.runSync(ConfigCallback.Reason.SYNC);
        }
    }

public static void onClientDisconnected() {
        for (Map.Entry<ResourceLocation, ConfigTag> entry : SYNC_MAP.entrySet()) {
            LOGGER.info("Client disconnected, rolling back config for {}.", entry.getKey());
            ConfigTag config = entry.getValue();
            config.resetFromNetwork();
            config.runSync(ConfigCallback.Reason.ROLLBACK);
        }
    }

