default int readVarInt() {
        int i = 0;
        int j = 0;
        byte b0;

        do {
            b0 = readByte();
            i |= (b0 & 0x7f) << j++ * 7;

            if (j > 5) {
                throw new RuntimeException("VarInt too big");
            }
        }
        while ((b0 & 0x80) == 0x80);

        return i;
    }

default long readVarLong() {
        long i = 0L;
        int j = 0;
        byte b0;

        do {
            b0 = readByte();
            i |= (long) (b0 & 0x7f) << j++ * 7;
            if (j > 10) {
                throw new RuntimeException("VarLong too big");
            }

        }
        while ((b0 & 0x80) == 0x80);

        return i;
    }

default int readSignedVarInt() {
        int i = readVarInt();
        return (i & 1) == 0 ? i >>> 1 : -(i >>> 1) - 1;
