            Fluid fluid = readRegistryIdDirect(ForgeRegistries.FLUIDS);
            int amount = readVarInt();
            CompoundTag tag = readCompoundNBT();
            if (fluid == Fluids.EMPTY) {
                return FluidStack.EMPTY;
