public static GuiDialog optionsDialog(@NotNull GuiParent<?> parent, @Nullable Component title, Component dialogText, Function<GuiDialog, GuiElement<?>> backgroundBuilder, BiFunction<GuiDialog, Option, GuiButton> buttonBuilder, int width, Option... options) {
        if (options.length == 0) throw new IllegalStateException("Can not create gui dialog with no options!");
        ModularGui gui = parent.getModularGui();

        GuiDialog dialog = new GuiDialog(gui.getRoot())
                .constrain(WIDTH, literal(width))
                .setOpaque(true);
        Constraints.bind(backgroundBuilder.apply(dialog), dialog);

        Constraint left = relative(dialog.get(LEFT), 5);
        Constraint right = relative(dialog.get(RIGHT), -5);

        if (title != null) {
            GuiText titleText = new GuiText(dialog, title)
                    .setWrap(true)
                    .constrain(TOP, relative(dialog.get(TOP), 5))
                    .constrain(LEFT, left)
                    .constrain(RIGHT, right)
                    .autoHeight();

            GuiText bodyText = new GuiText(dialog, dialogText)
                    .setWrap(true)
                    .constrain(TOP, relative(titleText.get(BOTTOM), 5))
                    .constrain(LEFT, left)
                    .constrain(RIGHT, right)
                    .autoHeight();
            dialog.constrain(HEIGHT, dynamic(() -> 5 + titleText.ySize() + 5 + bodyText.ySize() + 5 + 14 + 5));
        } else {
            GuiText bodyText = new GuiText(dialog, dialogText)
                    .setWrap(true)
                    .constrain(TOP, relative(dialog.get(TOP), 5))
                    .constrain(LEFT, left)
                    .constrain(RIGHT, right)
                    .autoHeight();
            dialog.constrain(HEIGHT, dynamic(() -> 5 + bodyText.ySize() + 5 + 14 + 5));
        }

        double totalWidth = FastStream.of(options).doubleSum(e -> dialog.font().width(e.text));
        double pos = 5;
        int spacing = 2;
        for (Option option : options) {
            double fraction = dialog.font().width(option.text) / totalWidth;
            double opWidth = (dialog.xSize() - 10 - ((options.length - 1) * spacing)) * fraction;
            buttonBuilder.apply(dialog, option)
                    .constrain(BOTTOM, relative(dialog.get(BOTTOM), -5))
                    .constrain(HEIGHT, literal(14))
                    .constrain(LEFT, relative(dialog.get(LEFT), pos).precise())
                    .constrain(WIDTH, literal(opWidth).precise());
            pos += opWidth + spacing;
        }

        dialog.constrain(TOP, midPoint(gui.get(TOP), gui.get(BOTTOM), () -> -(dialog.ySize() / 2D)));
        dialog.constrain(LEFT, midPoint(gui.get(LEFT), gui.get(RIGHT), -(width / 2D)));
        return dialog;
    }

private static GuiButton defaultButton(GuiDialog dialog, Option option) {
        GuiButton button = new GuiButton(dialog);

        GuiRectangle background = new GuiRectangle(button)
                .fill(() -> option.colour.apply(button.isMouseOver()));
        Constraints.bind(background, button);

        GuiText text = new GuiText(button, option.text());
        button.setLabel(text);
        Constraints.bind(text, button, 0, 2, 0, 2);

        button.onPress(() -> {
            if (option.action != null) {
                option.action.run();
            }
            dialog.close();
        });

        return button;
    }

public GuiElement(@NotNull GuiParent<?> parent) {
        this.parent = parent;
        this.parent.addChild(this);
    }

@NotNull
    @Override
    public GuiParent<?> getParent() {
        return parent;
    }

@Override
    public List<GuiElement<?>> getChildren() {
        return childElementsUnmodifiable;
    }

@Override
    public void addChild(GuiElement<?> child) {
        if (!initialized) throw new IllegalStateException("Attempted to add a child to an element before that element has been initialised!");
        if (child == this) throw new InvalidParameterException("Attempted to add element to itself as a child element.");
        if (child.getParent() != this) throw new UnsupportedOperationException("Attempted to add an already initialized element to a different parent element.");
        if (removeQueue.contains(child)) {
            removeQueue.remove(child);
            if (!childElements.contains(child)) {
                addedQueue.add(child);
            }
            child.initElement(this);
        } else if (!childElements.contains(child)) {
            addedQueue.add(child);
            child.initElement(this);
        }
    }

protected void applyQueuedChildUpdates() {
        if (!reorderMap.isEmpty()) {
            reorderMap.forEach((element, index) -> {
                if (!childElements.contains(element)) return;
                childElements.remove(element);
                childElements.add(Math.min(index, childElements.size()), element);
            });
            reorderMap.clear();
        }

        if (!removeQueue.isEmpty()) {
            childElements.removeAll(removeQueue);
            removeQueue.clear();
        }

        if (!addedQueue.isEmpty()) {
            childElements.addAll(addedQueue);
            addedQueue.forEach(ConstrainedGeometry::clearGeometryCache);
            addedQueue.clear();
        }
    }

public void initElement(GuiParent<?> parent) {
        removed = false;
        updateScreenData(parent.mc(), parent.font(), parent.scaledScreenWidth(), parent.scaledScreenHeight());
        initialized = true;
    }

@Override
    public void adoptChild(GuiElement<?> child) {
        child.getParent().removeChild(child);
        child.parent = this;
        addChild(child);
    }

@Override
    public void removeChild(GuiElement<?> child) {
        if (childElements.contains(child)) {
            child.removed = true;
            removeQueue.add(child);
        }
        addedQueue.remove(child);
    }

public void bringChildToForeground(GuiElement<?> child) {
        sendChildToIndex(child, childElements.size() - 1);
