private int getWordPosition(int i1, int i2, boolean b) {
        String value = getValue();
        int i = i2;
        boolean flag = i1 < 0;
        int j = Math.abs(i1);

        for (int k = 0; k < j; ++k) {
            if (!flag) {
                int l = value.length();
                i = value.indexOf(32, i);
                if (i == -1) {
                    i = l;
                } else {
                    while (b && i < l && value.charAt(i) == ' ') ++i;
                }
            } else {
                while (b && i > 0 && value.charAt(i - 1) == ' ') --i;
                while (i > 0 && value.charAt(i - 1) != ' ') --i;
            }
        }

        return i;
    }

