        return axis == Axis.X ? x() : y();
    }

default double max(Axis axis) {
        return axis == Axis.X ? xMax() : yMax();
    }

default double distance(Axis axis, Position position) {
        double pos = position.get(axis);
        double min = min(axis);
        double max = max(axis);
        return pos < min ? min - pos : pos > max ? pos - max : 0;
    }

