        clampBounds.set(bounds);
    }

@Override
    public boolean transform() {
        int s = quad.orientation.ordinal() >> 1;

        quad.clamp(clampBounds);

        // Check if the quad would be invisible and cull it.
        Vertex[] vertices = quad.vertices;
        float x1 = vertices[0].dx(s);
        float x2 = vertices[1].dx(s);
        float x3 = vertices[2].dx(s);
        float x4 = vertices[3].dx(s);

        float y1 = vertices[0].dy(s);
        float y2 = vertices[1].dy(s);
        float y3 = vertices[2].dy(s);
        float y4 = vertices[3].dy(s);

        // These comparisons are safe as we are comparing clamped values.
        boolean flag1 = x1 == x2 && x2 == x3 && x3 == x4;
        boolean flag2 = y1 == y2 && y2 == y3 && y3 == y4;
        return !flag1 && !flag2;
    }

QuadCornerKicker() {
        super();
    }

public void setSide(int side) {
        mySide = side;
    }

public void setFacadeMask(int mask) {
        facadeMask = mask;
    }

public void setBox(AABB box) {
        this.box = box;
    }

public void setThickness(double thickness) {
        this.thickness = thickness;
    }

@Override
    public boolean transform() {
        int side = quad.orientation.ordinal();
        if (side != mySide && side != (mySide ^ 1)) {
            for (int hoz : horizonals[mySide]) {
                if (side != hoz && side != (hoz ^ 1)) {
                    if ((facadeMask & (1 << hoz)) != 0) {
                        Corner corner = Corner.fromSides(mySide ^ 1, side, hoz);
                        for (Vertex vertex : quad.vertices) {
                            float x = vertex.vec[0];
                            float y = vertex.vec[1];
                            float z = vertex.vec[2];
                            if (epsComp(x, corner.pX(box)) && epsComp(y, corner.pY(box)) && epsComp(z, corner.pZ(box))) {
                                Vec3i vec = Direction.BY_3D_DATA[hoz].getNormal();
                                x -= vec.getX() * thickness;
                                y -= vec.getY() * thickness;
                                z -= vec.getZ() * thickness;
                                vertex.vec[0] = x;
                                vertex.vec[1] = y;
                                vertex.vec[2] = z;
                            }
                        }
                    }
                }
            }
        }

        return true;
