@Override
    public boolean transform() {
        // Nuke tintIndex.
        quad.tintIndex = -1;
        if (format.hasColor) {
            float r = (tint >> 0x10 & 0xFF) / 255F;
            float g = (tint >> 0x08 & 0xFF) / 255F;
            float b = (tint & 0xFF) / 255F;
            for (Vertex v : quad.vertices) {
                v.color[0] *= r;
                v.color[1] *= g;
                v.color[2] *= b;
            }
        }
        return true;
    }

