        return new Quaterniond(x, y, z, s);
    }

public double mag() {
        return Math.sqrt(x * x + y * y + z * z + s * s);
    }

public Quat normalize() {
        double d = mag();
        if (d != 0) {
            d = 1 / d;
            x *= d;
            y *= d;
            z *= d;
            s *= d;
        }

        return this;
    }

