public static int getSidedRotation(Player player, int side) {
        Vector3 look = new Vector3(player.getViewVector(1));
        double max = 0;
        int maxr = 0;
        for (int r = 0; r < 4; r++) {
            Vector3 axis = Rotation.axes[rotateSide(side ^ 1, r)];
            double d = look.scalarProject(axis);
            if (d > max) {
                max = d;
                maxr = r;
            }
        }
        return maxr;
    }

